   0 import React, { useState, useEffect } from 'react';
   1 import ReactMarkdown from 'react-markdown';
   2 import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
   3 import { oneDark } from 'react-syntax-highlighter/dist/esm/styles/prism';
   4 
   5 interface StreamingTextProps {
   6   content: string;
   7   isStreaming: boolean;
   8   speed?: number; // characters per interval
   9 }
  10 
  11 const StreamingText: React.FC<StreamingTextProps> = ({ 
  12   content, 
  13   isStreaming, 
  14   speed = 3 
  15 }) => {
  16   const [displayedContent, setDisplayedContent] = useState('');
  17   const [currentIndex, setCurrentIndex] = useState(0);
  18 
  19   useEffect(() => {
  20     if (!isStreaming) {
  21       // If not streaming, show full content immediately
  22       setDisplayedContent(content);
  23       setCurrentIndex(content.length);
  24       return;
  25     }
  26 
  27     // Typewriter effect
  28     if (currentIndex < content.length) {
  29       const timer = setTimeout(() => {
  30         const nextIndex = Math.min(currentIndex + speed, content.length);
  31         setDisplayedContent(content.slice(0, nextIndex));
  32         setCurrentIndex(nextIndex);
  33       }, 30); // 30ms interval for smooth animation
  34 
  35       return () => clearTimeout(timer);
  36     }
  37   }, [content, currentIndex, isStreaming, speed]);
  38 
  39   // Reset when content changes significantly (new message)
  40   useEffect(() => {
  41     if (content.length < displayedContent.length) {
  42       setDisplayedContent('');
  43       setCurrentIndex(0);
  44     }
  45   }, [content.length, displayedContent.length]);
  46 
  47   return (
  48     <div className="relative">
  49       <ReactMarkdown
  50         className="prose prose-sm max-w-none"
  51         components={{
  52           code({ node, inline, className, children, ...props }) {
  53             const match = /language-(\w+)/.exec(className || '');
  54             return !inline && match ? (
  55               <SyntaxHighlighter
  56                 style={oneDark}
  57                 language={match[1]}
  58                 PreTag="div"
  59                 className="rounded-md my-2"
  60                 {...props}
  61               >
  62                 {String(children).replace(/\n$/, '')}
  63               </SyntaxHighlighter>
  64             ) : (
  65               <code className="bg-gray-100 text-red-600 px-1 py-0.5 rounded text-sm" {...props}>
  66                 {children}
  67               </code>
  68             );
  69           },
  70           p({ children }) {
  71             return <p className="mb-2 last:mb-0">{children}</p>;
  72           },
  73           ul({ children }) {
  74             return <ul className="list-disc list-inside mb-2 space-y-1">{children}</ul>;
  75           },
  76           ol({ children }) {
  77             return <ol className="list-decimal list-inside mb-2 space-y-1">{children}</ol>;
  78           },
  79           h1({ children }) {
  80             return <h1 className="text-xl font-bold mb-2 mt-3">{children}</h1>;
  81           },
  82           h2({ children }) {
  83             return <h2 className="text-lg font-bold mb-2 mt-3">{children}</h2>;
  84           },
  85           h3({ children }) {
  86             return <h3 className="text-md font-semibold mb-2 mt-2">{children}</h3>;
  87           },
  88           blockquote({ children }) {
  89             return (
  90               <blockquote className="border-l-4 border-gray-300 pl-4 italic my-2 text-gray-700">
  91                 {children}
  92               </blockquote>
  93             );
  94           },
  95           a({ href, children }) {
  96             return (
  97               <a 
  98                 href={href} 
  99                 className="text-blue-600 hover:underline" 
 100                 target="_blank" 
 101                 rel="noopener noreferrer"
 102               >
 103                 {children}
 104               </a>
 105             );
 106           },
 107         }}
 108       >
 109         {displayedContent}
 110       </ReactMarkdown>
 111       
 112       {/* Blinking cursor during streaming */}
 113       {isStreaming && currentIndex < content.length && (
 114         <span className="inline-block w-2 h-4 bg-blue-600 ml-1 animate-blink" />
 115       )}
 116     </div>
 117   );
 118 };
 119 
 120 export default StreamingText;
 121 
