   0 import axios, { AxiosInstance } from 'axios';
   1 
   2 const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000';
   3 
   4 class ApiService {
   5   private client: AxiosInstance;
   6 
   7   constructor() {
   8     this.client = axios.create({
   9       baseURL: API_URL,
  10       headers: {
  11         'Content-Type': 'application/json',
  12       },
  13     });
  14   }
  15 
  16   // Upload document
  17   async uploadDocument(file: File): Promise<{
  18     success: boolean;
  19     document_id: string;
  20     filename: string;
  21     chunks: number;
  22     characters: number;
  23     message: string;
  24   }> {
  25     const formData = new FormData();
  26     formData.append('file', file);
  27 
  28     const response = await this.client.post('/api/upload', formData, {
  29       headers: {
  30         'Content-Type': 'multipart/form-data',
  31       },
  32     });
  33 
  34     return response.data;
  35   }
  36 
  37   // List documents
  38   async listDocuments(): Promise<Array<{
  39     document_id: string;
  40     filename: string;
  41     file_type: string;
  42     size: number;
  43   }>> {
  44     const response = await this.client.get('/api/documents');
  45     return response.data;
  46   }
  47 
  48   // Delete document
  49   async deleteDocument(documentId: string): Promise<{
  50     success: boolean;
  51     document_id: string;
  52     chunks_deleted: number;
  53     message: string;
  54   }> {
  55     const response = await this.client.delete(`/api/documents/${documentId}`);
  56     return response.data;
  57   }
  58 
  59   // Chat (non-streaming)
  60   async chat(question: string, documentId?: string, topK: number = 5): Promise<{
  61     answer: string;
  62     sources: Array<{
  63       filename: string;
  64       chunk_id: number;
  65       score: number;
  66       text: string;
  67     }>;
  68   }> {
  69     const response = await this.client.post('/api/chat', {
  70       question,
  71       document_id: documentId,
  72       top_k: topK,
  73       stream: false,
  74     });
  75 
  76     return response.data;
  77   }
  78 
  79   // Chat streaming
  80   async chatStream(
  81     question: string,
  82     onChunk: (chunk: string) => void,
  83     onSources: (sources: any[]) => void,
  84     onError: (error: Error) => void,
  85     onComplete: () => void,
  86     documentId?: string,
  87     topK: number = 5,
  88     model?: string
  89   ): Promise<void> {
  90     try {
  91       const response = await fetch(`${API_URL}/api/chat`, {
  92         method: 'POST',
  93         headers: {
  94           'Content-Type': 'application/json',
  95         },
  96         body: JSON.stringify({
  97           question,
  98           document_id: documentId,
  99           top_k: topK,
 100           stream: true,
 101           model: model,
 102         }),
 103       });
 104 
 105       if (!response.ok) {
 106         throw new Error(`HTTP error! status: ${response.status}`);
 107       }
 108 
 109       const reader = response.body?.getReader();
 110       if (!reader) {
 111         throw new Error('No response body');
 112       }
 113 
 114       const decoder = new TextDecoder();
 115       let buffer = '';
 116 
 117       while (true) {
 118         const { done, value } = await reader.read();
 119         if (done) break;
 120 
 121         buffer += decoder.decode(value, { stream: true });
 122         const lines = buffer.split('\n');
 123         buffer = lines.pop() || '';
 124 
 125         for (const line of lines) {
 126           if (line.startsWith('data: ')) {
 127             const data = line.slice(6);
 128             
 129             if (data === '[DONE]') {
 130               onComplete();
 131               return;
 132             }
 133 
 134             try {
 135               const parsed = JSON.parse(data);
 136               if (parsed.type === 'sources') {
 137                 onSources(parsed.data);
 138               } else if (parsed.type === 'answer') {
 139                 onChunk(parsed.data);
 140               }
 141             } catch (e) {
 142               // Ignore parse errors
 143             }
 144           }
 145         }
 146       }
 147 
 148       onComplete();
 149     } catch (error) {
 150       onError(error as Error);
 151     }
 152   }
 153 
 154   // Get available models
 155   async getModels(): Promise<{
 156     models: Array<{
 157       name: string;
 158       full_name: string;
 159       size: number;
 160       modified: string;
 161       description: string;
 162     }>;
 163     default: string;
 164   }> {
 165     const response = await this.client.get('/api/models');
 166     return response.data;
 167   }
 168 
 169   // Health check
 170   async healthCheck(): Promise<{
 171     api: string;
 172     qdrant: string;
 173     ollama: string;
 174   }> {
 175     const response = await this.client.get('/health');
 176     return response.data;
 177   }
 178 }
 179 
 180 export default new ApiService();
 181 
